package org.example.server.persistence.repository;
import jakarta.persistence.LockModeType;import org.example.server.persistence.entity.PurchaseHeaderEntity;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import java.util.*;
public interface PurchaseHeaderRepository extends JpaRepository<PurchaseHeaderEntity,Integer>{Optional<PurchaseHeaderEntity> findByInvoiceNo(String invoiceNo);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select purchase from PurchaseHeaderEntity purchase where purchase.id=:id") Optional<PurchaseHeaderEntity> findByIdForUpdate(@Param("id") Integer id); boolean existsByInvoiceNo(String invoiceNo); List<PurchaseHeaderEntity> findAllByOrderByInvoiceDateDescIdDesc();}
